	var totalDocs int64
	b.cacheMu.RLock()
	defer b.cacheMu.RUnlock()
	for _, v := range b.cache {
		c, err := v.index.DocCount()
		if err != nil {
			continue
		}
		totalDocs += int64(c)
	}
	return totalDocs

